//! Open-source license notices shown on the info screen.
//!
//! Two files are embedded at compile time: `licenses/rust-crates.txt` (generated by
//! `scripts/update-licenses.sh` with cargo-about) and `licenses/other-components.txt` (hand-maintained:
//! Slint, Skia with its bundled libraries, Kotlin). Both use the same plain-text format, one section per
//! license text:
//!
//! ```text
//! @@@@ LICENSE <license name>
//! @@@@ PACKAGES <package 1.0, package 2.0>
//! @@@@ TEXT
//! <full license text, any number of lines>
//! ```
//!
//! A marker line starts with `@@@@ ` at the very beginning of a line; license texts never contain one.

const MARKER: &str = "@@@@ ";
const LICENSE_MARKER: &str = "@@@@ LICENSE";
const PACKAGES_MARKER: &str = "@@@@ PACKAGES ";
const TEXT_MARKER: &str = "@@@@ TEXT";

/// Hand-maintained notices come first: Slint is the license with the strictest display duty.
const OTHER_COMPONENTS: &str = include_str!("../licenses/other-components.txt");
const RUST_CRATES: &str = include_str!("../licenses/rust-crates.txt");

/// One license section: a license text and the packages it applies to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct LicenseEntry {
    pub(crate) name: String,
    /// Comma-separated list of the packages covered by this license text.
    pub(crate) packages: String,
    pub(crate) text: String,
}

/// All license entries shipped with the app.
pub(crate) fn all() -> Vec<LicenseEntry> {
    let mut entries = parse(OTHER_COMPONENTS);
    entries.extend(parse(RUST_CRATES));
    entries
}

/// Which part of an entry the parser is currently reading.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Part {
    Header,
    Text,
}

/// Parses the license file format. Never fails: text before the first `LICENSE` marker, unknown markers
/// and sections without a name or text are skipped (logged), so a damaged file cannot break the app.
pub(crate) fn parse(source: &str) -> Vec<LicenseEntry> {
    let mut entries = Vec::new();
    let mut current: Option<(LicenseEntry, Part)> = None;

    for line in source.lines() {
        // Also matches a bare `@@@@ LICENSE` line: that starts a (nameless, hence skipped) section.
        let license_name = line
            .strip_prefix(LICENSE_MARKER)
            .filter(|rest| rest.is_empty() || rest.starts_with(' '));
        if let Some(name) = license_name {
            finish(&mut entries, current.take());
            let entry = LicenseEntry {
                name: name.trim().to_owned(),
                packages: String::new(),
                text: String::new(),
            };
            current = Some((entry, Part::Header));
        } else if line.starts_with(MARKER) {
            let Some((entry, part)) = current.as_mut() else {
                continue;
            };
            if let Some(packages) = line.strip_prefix(PACKAGES_MARKER) {
                entry.packages = packages.trim().to_owned();
            } else if line.trim_end() == TEXT_MARKER {
                *part = Part::Text;
            } else {
                log::warn!("unknown marker in license file: {line}");
            }
        } else if let Some((entry, Part::Text)) = current.as_mut() {
            entry.text.push_str(line);
            entry.text.push('\n');
        }
    }
    finish(&mut entries, current);
    entries
}

/// Stores a finished entry if it has a name and a text.
fn finish(entries: &mut Vec<LicenseEntry>, current: Option<(LicenseEntry, Part)>) {
    let Some((mut entry, _)) = current else {
        return;
    };
    entry.text = entry.text.trim().to_owned();
    if entry.name.is_empty() || entry.text.is_empty() {
        log::warn!("skipping incomplete license entry {:?}", entry.name);
    } else {
        entries.push(entry);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "\
@@@@ LICENSE MIT License
@@@@ PACKAGES foo 1.0, bar 2.1
@@@@ TEXT
Permission is hereby granted.

Second paragraph.
@@@@ LICENSE Apache License 2.0
@@@@ PACKAGES baz 0.3
@@@@ TEXT
Apache text
";

    #[test]
    fn parses_entries_with_name_packages_and_multiline_text() {
        let entries = parse(SAMPLE);
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[0].name, "MIT License");
        assert_eq!(entries[0].packages, "foo 1.0, bar 2.1");
        assert_eq!(
            entries[0].text,
            "Permission is hereby granted.\n\nSecond paragraph."
        );
        assert_eq!(entries[1].name, "Apache License 2.0");
        assert_eq!(entries[1].text, "Apache text");
    }

    #[test]
    fn empty_input_gives_no_entries() {
        assert!(parse("").is_empty());
        assert!(parse("\n\n").is_empty());
    }

    #[test]
    fn malformed_input_is_skipped_without_panic() {
        // Text before any marker, a section without text, a section without name, an unknown marker and
        // a marker without trailing content.
        let source = "\
stray line
@@@@ PACKAGES orphan 1.0
@@@@ LICENSE No text
@@@@ PACKAGES a 1
@@@@ LICENSE
@@@@ TEXT
nameless text
@@@@ BOGUS
@@@@ LICENSE Good
@@@@ BOGUS marker
@@@@ TEXT
kept
";
        let entries = parse(source);
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].name, "Good");
        assert_eq!(entries[0].text, "kept");
        assert_eq!(entries[0].packages, "");
    }

    #[test]
    fn text_without_text_marker_is_not_collected() {
        assert!(parse("@@@@ LICENSE X\nlooks like text\n").is_empty());
    }

    #[test]
    fn marker_inside_a_line_is_plain_text() {
        let entries = parse("@@@@ LICENSE X\n@@@@ TEXT\nsee @@@@ LICENSE Y\n");
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].text, "see @@@@ LICENSE Y");
    }

    #[test]
    fn embedded_files_contain_the_required_notices() {
        let entries = all();
        assert!(entries.len() > 50, "got {} entries", entries.len());
        assert!(entries.iter().all(|e| !e.text.is_empty()));
        let has = |needle: &str| {
            entries
                .iter()
                .any(|e| e.name.contains(needle) || e.packages.contains(needle))
        };
        assert!(has("Slint Royalty-free"));
        assert!(has("Skia"));
        assert!(has("kotlin-stdlib"));
        assert!(has("slint 1."));
        assert!(!has("collage-core"), "private crates are not listed");
    }
}
